  width: 400px;
}

.register-header {
  margin-bottom: 20px;
  text-align: center;
}

.logo {
  width: 80px;
}

.register-form {
  max-width: 350px;
  margin: 0 auto;
}

.register-btn {
  margin-top: 20px;
  padding: 10px;
  font-size: 16px;
}

